import{_ as t,o,c as a,a2 as d}from"./chunks/framework.D6sNNOyC.js";const u=JSON.parse('{"title":"Referencia","description":"Všetky verejné triedy a rozhrania Nette API 3.x podľa namespace, s jednoriadkovým popisom a odkazom na stránku príručky.","frontmatter":{"title":"Referencia","description":"Všetky verejné triedy a rozhrania Nette API 3.x podľa namespace, s jednoriadkovým popisom a odkazom na stránku príručky."},"headers":[],"relativePath":"sk/api/reference.md","filePath":"sk/api/reference.md","lastUpdated":1793254422000}'),r={name:"sk/api/reference.md"};function i(n,e,c,p,s,l){return o(),a("div",null,[...e[0]||(e[0]=[d('<h1 id="referencia" tabindex="-1">Referencia <a class="header-anchor" href="#referencia" aria-label="Permalink to &quot;Referencia&quot;">​</a></h1><p>Všetky triedy sú pod <code>Tomaj\\NetteApi</code>.</p><h2 id="jadro" tabindex="-1">Jadro <a class="header-anchor" href="#jadro" aria-label="Permalink to &quot;Jadro&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Trieda</th><th>Čo robí</th><th>Príručka</th></tr></thead><tbody><tr><td><code>ApiDecider</code></td><td>register endpointov: <code>addApi()</code>, <code>getApi()</code>, <code>getApis()</code>, <code>enableGlobalPreflight()</code></td><td><a href="/nette-api/pr-preview/pr-222/sk/guide/architecture.html">Architektúra</a></td></tr><tr><td><code>Api</code></td><td>jeden zaregistrovaný endpoint: endpoint, handler, autorizácia, obmedzenie požiadaviek</td><td><a href="/nette-api/pr-preview/pr-222/sk/guide/architecture.html">Architektúra</a></td></tr><tr><td><code>ApiHolder</code></td><td>používa ho <code>ApiDecider</code>: ako uchováva endpoint pred vytvorením handlera; handler môže byť ešte názov triedy alebo služby</td><td><a href="/nette-api/pr-preview/pr-222/sk/guide/api-decider.html#tri-sposoby-ako-odovzdat-handler">ApiDecider</a></td></tr><tr><td><code>EndpointIdentifier</code> / <code>EndpointInterface</code></td><td>metóda, verzia, balík, akcia</td><td><a href="/nette-api/pr-preview/pr-222/sk/guide/handlers.html#registracia-handlera">Handlery</a></td></tr><tr><td><code>Presenters\\ApiPresenter</code></td><td>spracuje požiadavku krok po kroku</td><td><a href="/nette-api/pr-preview/pr-222/sk/guide/presenter.html">Spracovanie v ApiPresenteri</a></td></tr></tbody></table><h2 id="handlery" tabindex="-1">Handlery <a class="header-anchor" href="#handlery" aria-label="Permalink to &quot;Handlery&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Trieda</th><th>Čo robí</th><th>Príručka</th></tr></thead><tbody><tr><td><code>Handlers\\ApiHandlerInterface</code>, <code>BaseHandler</code></td><td>vaše endpointy</td><td><a href="/nette-api/pr-preview/pr-222/sk/guide/handlers.html">Handlery</a></td></tr><tr><td><code>Handlers\\OpenApiHandler</code></td><td>OpenAPI 3.0 dokument</td><td><a href="/nette-api/pr-preview/pr-222/sk/guide/openapi.html">OpenAPI</a></td></tr><tr><td><code>Handlers\\ApiListingHandler</code></td><td>JSON zoznam endpointov vo vlastnej verzii</td><td><a href="/nette-api/pr-preview/pr-222/sk/guide/handlers.html#handlery-ktore-su-sucastou-kniznice">Handlery</a></td></tr><tr><td><code>Handlers\\AlwaysOkHandler</code>, <code>EchoHandler</code></td><td>health check a testovacie endpointy</td><td><a href="/nette-api/pr-preview/pr-222/sk/guide/handlers.html#handlery-ktore-su-sucastou-kniznice">Handlery</a></td></tr><tr><td><code>Handlers\\DefaultHandler</code></td><td><code>404 Unknown api endpoint</code></td><td><a href="/nette-api/pr-preview/pr-222/sk/guide/architecture.html">Architektúra</a></td></tr><tr><td><code>Handlers\\CorsPreflightHandler(Interface)</code></td><td>odpovedá na <code>OPTIONS</code></td><td><a href="/nette-api/pr-preview/pr-222/sk/guide/cors.html#preflight-poziadavky">CORS</a></td></tr></tbody></table><h2 id="parametre-a-validacia" tabindex="-1">Parametre a validácia <a class="header-anchor" href="#parametre-a-validacia" aria-label="Permalink to &quot;Parametre a validácia&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Trieda</th><th>Čo robí</th><th>Príručka</th></tr></thead><tbody><tr><td><code>Params\\GetInputParam</code>, <code>PostInputParam</code>, <code>PutInputParam</code>, <code>CookieInputParam</code>, <code>FileInputParam</code>, <code>RawInputParam</code>, <code>JsonInputParam</code></td><td>každá jeden vstup</td><td><a href="/nette-api/pr-preview/pr-222/sk/guide/params.html">Parametre</a></td></tr><tr><td><code>Params\\InputParam</code>, <code>ParamInterface</code>, <code>ParamsProcessor</code></td><td>základná trieda a spracovanie</td><td><a href="/nette-api/pr-preview/pr-222/sk/guide/params.html">Parametre</a></td></tr><tr><td><code>Validation\\InputValidator</code>, <code>JsonSchemaValidator</code>, <code>InputType</code> (enum)</td><td>kontroly hodnôt</td><td><a href="/nette-api/pr-preview/pr-222/sk/guide/params.html#typy">Parametre</a></td></tr><tr><td><code>ValidationResult\\ValidationResult(Interface)</code></td><td>výsledok kontroly</td><td><a href="/nette-api/pr-preview/pr-222/sk/guide/params.html">Parametre</a></td></tr></tbody></table><h2 id="odpovede-a-vystupy" tabindex="-1">Odpovede a výstupy <a class="header-anchor" href="#odpovede-a-vystupy" aria-label="Permalink to &quot;Odpovede a výstupy&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Trieda</th><th>Čo robí</th><th>Príručka</th></tr></thead><tbody><tr><td><code>Response\\ResponseInterface</code></td><td>čo implementuje každá odpoveď</td><td><a href="/nette-api/pr-preview/pr-222/sk/guide/outputs.html#odpovede">Výstupy</a></td></tr><tr><td><code>Response\\JsonApiResponse</code>, <code>TextApiResponse</code>, <code>XmlApiResponse</code>, <code>RedirectResponse</code></td><td>čo vracia <code>handle()</code></td><td><a href="/nette-api/pr-preview/pr-222/sk/guide/outputs.html#odpovede">Výstupy</a></td></tr><tr><td><code>Output\\JsonOutput</code>, <code>RedirectOutput</code>, <code>AbstractOutput</code>, <code>OutputInterface</code></td><td>deklarované výstupy</td><td><a href="/nette-api/pr-preview/pr-222/sk/guide/outputs.html#vystupy">Výstupy</a></td></tr><tr><td><code>Output\\Configurator\\ConfiguratorInterface</code>, <code>EnvConfigurator</code>, <code>QueryConfigurator</code>, <code>DebuggerConfigurator</code></td><td>kedy kontrolovať výstupy a zobrazovať detaily</td><td><a href="/nette-api/pr-preview/pr-222/sk/guide/outputs.html#kedy-sa-vystupy-validuju">Výstupy</a></td></tr><tr><td><code>Error\\ErrorHandlerInterface</code>, <code>DefaultErrorHandler</code></td><td>chybové odpovede</td><td><a href="/nette-api/pr-preview/pr-222/sk/guide/errors.html">Spracovanie chýb</a></td></tr><tr><td><code>Error\\ProblemDetailsErrorHandler</code>, <code>NegotiatingErrorHandler</code>, <code>ProblemDetails</code>, <code>Response\\ProblemDetailsResponse</code></td><td>chyby podľa RFC 9457, 4.0.0</td><td><a href="/nette-api/pr-preview/pr-222/sk/guide/problem-details.html">Problem Details</a></td></tr></tbody></table><h2 id="bezpecnost" tabindex="-1">Bezpečnosť <a class="header-anchor" href="#bezpecnost" aria-label="Permalink to &quot;Bezpečnosť&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Trieda</th><th>Čo robí</th><th>Príručka</th></tr></thead><tbody><tr><td><code>Authorization\\NoAuthorization</code>, <code>BearerTokenAuthorization</code>, <code>HeaderApiKeyAuthentication</code>, <code>QueryApiKeyAuthentication</code>, <code>CookieApiKeyAuthentication</code>, <code>BasicAuthentication</code></td><td>vstavaná autorizácia</td><td><a href="/nette-api/pr-preview/pr-222/sk/guide/authorization.html">Autorizácia</a></td></tr><tr><td><code>Authorization\\ApiAuthorizationInterface</code>, <code>TokenAuthorization</code></td><td>vlastná autorizácia</td><td><a href="/nette-api/pr-preview/pr-222/sk/guide/authorization.html#vlastna-autorizacia">Autorizácia</a></td></tr><tr><td><code>Misc\\TokenRepositoryInterface</code>, <code>StaticTokenRepository</code></td><td>tokeny a ich IP</td><td><a href="/nette-api/pr-preview/pr-222/sk/guide/authorization.html#tokeny-a-obmedzenie-ip">Autorizácia</a></td></tr><tr><td><code>Misc\\IpDetectorInterface</code>, <code>IpDetector</code>, <code>StaticIpDetector</code></td><td>IP klienta</td><td><a href="/nette-api/pr-preview/pr-222/sk/guide/authorization.html#tokeny-a-obmedzenie-ip">Autorizácia</a></td></tr><tr><td><code>RateLimit\\RateLimitInterface</code>, <code>RateLimitResponse</code>, <code>NoRateLimit</code></td><td>obmedzenie požiadaviek</td><td><a href="/nette-api/pr-preview/pr-222/sk/guide/rate-limit.html">Obmedzenie požiadaviek</a></td></tr></tbody></table><h2 id="logovanie-odkazy-a-konzola" tabindex="-1">Logovanie, odkazy a konzola <a class="header-anchor" href="#logovanie-odkazy-a-konzola" aria-label="Permalink to &quot;Logovanie, odkazy a konzola&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Trieda</th><th>Čo robí</th><th>Príručka</th></tr></thead><tbody><tr><td><code>Logger\\ApiLoggerInterface</code></td><td>log požiadaviek</td><td><a href="/nette-api/pr-preview/pr-222/sk/guide/logging.html">Logovanie</a></td></tr><tr><td><code>Link\\ApiLink</code>, <code>ApiLinkExtension</code>, <code>ApiLinkNode</code></td><td>URL a tag <code>{apiLink}</code></td><td><a href="/nette-api/pr-preview/pr-222/sk/guide/links.html">Odkazy</a></td></tr><tr><td><code>Component\\ApiListingControl</code>, <code>ApiConsoleControl</code>, <code>ApiConsoleFormFactoryInterface</code>, <code>DefaultApiConsoleFormFactory</code></td><td>webová konzola</td><td><a href="/nette-api/pr-preview/pr-222/sk/guide/console.html">Webová konzola</a></td></tr><tr><td><code>Misc\\ConsoleRequest</code>, <code>ConsoleResponse</code></td><td>cURL požiadavka konzoly</td><td><a href="/nette-api/pr-preview/pr-222/sk/guide/console.html">Webová konzola</a></td></tr><tr><td><code>Misc\\CorsOriginAllowlist</code></td><td>interné (<code>@internal</code>), používa ho <code>setCorsAllowedOrigins()</code>; vo 4.0 sa môže zmeniť</td><td><a href="/nette-api/pr-preview/pr-222/sk/guide/cors.html#povolene-originy">CORS</a></td></tr><tr><td><code>Misc\\OpenApiTransform</code></td><td>pomocné funkcie pre OpenAPI</td><td><a href="/nette-api/pr-preview/pr-222/sk/guide/openapi.html">OpenAPI</a></td></tr></tbody></table><h2 id="caste-otazky" tabindex="-1">Časté otázky <a class="header-anchor" href="#caste-otazky" aria-label="Permalink to &quot;Časté otázky&quot;">​</a></h2><h3 id="ktore-triedy-su-final" tabindex="-1">Ktoré triedy sú final? <a class="header-anchor" href="#ktore-triedy-su-final" aria-label="Permalink to &quot;Ktoré triedy sú final?&quot;">​</a></h3><p><code>Presenters\\ApiPresenter</code>, <code>Error\\DefaultErrorHandler</code>, Latte triedy <code>Link\\ApiLinkExtension</code> a <code>Link\\ApiLinkNode</code> a interná <code>Misc\\CorsOriginAllowlist</code> sú <code>final</code>; namiesto dedenia ich obaľte. Pozrite si <a href="/nette-api/pr-preview/pr-222/sk/guide/errors.html#vlastny-error-handler">Spracovanie chýb</a>.</p><p>Od verzie 4.0 sú <code>final</code> aj: <code>Api</code>, <code>ApiHolder</code>, <code>EndpointIdentifier</code>, <code>Authorization\\NoAuthorization</code>, <code>RateLimit\\NoRateLimit</code>, <code>RateLimit\\RateLimitResponse</code>, <code>Misc\\IpDetector</code>, <code>Misc\\StaticIpDetector</code>, <code>Misc\\StaticTokenRepository</code>, <code>Misc\\ConsoleRequest</code>, <code>Misc\\ConsoleResponse</code>, <code>Misc\\OpenApiTransform</code>, <code>Params\\ParamsProcessor</code>, <code>Validation\\InputValidator</code>, <code>Validation\\JsonSchemaValidator</code>, <code>ValidationResult\\ValidationResult</code>, výstupné konfigurátory <code>DebuggerConfigurator</code>, <code>EnvConfigurator</code> a <code>QueryConfigurator</code> a <code>OpenApi\\SchemaRegistry</code> a <code>OpenApi\\EndpointFilter</code>. Namiesto dedenia implementujte príslušné rozhranie (<code>IpDetectorInterface</code>, <code>TokenRepositoryInterface</code>, <code>ApiAuthorizationInterface</code>, <code>RateLimitInterface</code>, <code>ConfiguratorInterface</code>, …). Handlery, parametre, výstupy, odpovede, autorizácie, OpenAPI buildery, <code>ApiDecider</code>, <code>ApiLink</code>, komponenty konzoly a <code>DefaultApiConsoleFormFactory</code> sa dajú ďalej rozširovať.</p><h3 id="kde-najdem-signatury-metod" tabindex="-1">Kde nájdem signatúry metód? <a class="header-anchor" href="#kde-najdem-signatury-metod" aria-label="Permalink to &quot;Kde nájdem signatúry metód?&quot;">​</a></h3><p>V zdrojovom kóde na <a href="https://github.com/tomaj/nette-api/tree/master/src" target="_blank" rel="noreferrer">GitHube</a>; stránky príručky ukazujú tie, ktoré používate.</p><h3 id="ktore-triedy-su-zastarane" tabindex="-1">Ktoré triedy sú zastarané? <a class="header-anchor" href="#ktore-triedy-su-zastarane" aria-label="Permalink to &quot;Ktoré triedy sú zastarané?&quot;">​</a></h3><p>Žiadne. <code>setExample()</code> pri parametroch a výstupoch bolo vo verzii 4.0 odstránené; použite <code>addExample()</code>. Staré <code>StaticBearerTokenRepository</code> a <code>BearerTokenRepositoryInterface</code> boli vo verzii 4.0 odstránené. Použite <code>StaticTokenRepository</code> a <code>TokenRepositoryInterface</code>, ktoré fungujú rovnako.</p><h3 id="existuje-di-rozsirenie" tabindex="-1">Existuje DI rozšírenie? <a class="header-anchor" href="#existuje-di-rozsirenie" aria-label="Permalink to &quot;Existuje DI rozšírenie?&quot;">​</a></h3><p>Nie, všetko sa registruje ako bežné služby v NEON, pozrite si <a href="/nette-api/pr-preview/pr-222/sk/guide/getting-started.html">Začíname</a>.</p><h3 id="ako-vyzera-cely-projekt" tabindex="-1">Ako vyzerá celý projekt? <a class="header-anchor" href="#ako-vyzera-cely-projekt" aria-label="Permalink to &quot;Ako vyzerá celý projekt?&quot;">​</a></h3><p>Pozrite si <a href="/nette-api/pr-preview/pr-222/sk/examples/">príklady</a>.</p>',26)])])}const k=t(r,[["render",i]]);export{u as __pageData,k as default};
